const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-122.107805, 39.493523);
  const radiusMiles = 10;
  const radiusMeters = radiusMiles * 1609.34; // Convert miles to meters
  const geometry = point.buffer(radiusMeters);

  const date1_start = '2021-08-30'; // September 4, 2021 +/- 5 days
  const date1_end = '2021-09-09';
  const date2_start = '2022-09-11'; // September 16, 2022 +/- 5 days
  const date2_end = '2022-09-21';

  // Sentinel-2 Level-2A (Surface Reflectance)
  const collectionId = 'COPERNICUS/S2_SR_HARMONIZED';

  // Function to mask clouds based on SCL band
  function maskS2clouds(image) {
    const scl = image.select('SCL');
    // Clouds, cloud shadows, cirrus, snow/ice, saturated
    const invalidPixels = scl.eq(3).or(scl.eq(8)).or(scl.eq(9)).or(scl.eq(10)).or(scl.eq(11));
    return image.updateMask(invalidPixels.not());
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 2. Data Acquisition & Check for Period 1
  let collection1 = ee.ImageCollection(collectionId)
    .filterBounds(geometry)
    .filterDate(date1_start, date1_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Initial cloud filter
    .map(maskS2clouds)
    .map(addNDVI)
    .select('NDVI');

  const size1 = await collection1.size().getInfo();
  if (size1 === 0) {
    console.log(`No Sentinel-2 images found for period 1 (${date1_start} to ${date1_end}).`);
    console.log('C1');
    return;
  }
  const image1 = collection1.median().clip(geometry);

  // 3. Data Acquisition & Check for Period 2
  let collection2 = ee.ImageCollection(collectionId)
    .filterBounds(geometry)
    .filterDate(date2_start, date2_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Initial cloud filter
    .map(maskS2clouds)
    .map(addNDVI)
    .select('NDVI');

  const size2 = await collection2.size().getInfo();
  if (size2 === 0) {
    console.log(`No Sentinel-2 images found for period 2 (${date2_start} to ${date2_end}).`);
    console.log('C1');
    return;
  }
  const image2 = collection2.median().clip(geometry);

  // Define scale for reduction (10m for Sentinel-2, but aggregated for speed)
  const scale = 100; // Using 100m for reduction

  // Calculate valid pixel count for image 1
  const count1 = await image1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count1 === 0) {
    console.log(`No valid pixels remaining for period 1 (${date1_start} to ${date1_end}) after masking.`);
    console.log('C2');
    return;
  }

  // Calculate valid pixel count for image 2
  const count2 = await image2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count2 === 0) {
    console.log(`No valid pixels remaining for period 2 (${date2_start} to ${date2_end}) after masking.`);
    console.log('C2');
    return;
  }

  // Calculate mean NDVI for each period
  const meanNDVI1 = await image1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const meanNDVI2 = await image2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 4. Validation & Final Answer
  if (meanNDVI1 === null || isNaN(meanNDVI1) || meanNDVI2 === null || isNaN(meanNDVI2)) {
    console.log('NDVI calculation resulted in null/NaN values.');
    console.log('C3');
    return;
  }

  console.log(`Period 1 Images: ${size1}, Valid Pixels: ${count1}`);
  console.log(`Period 2 Images: ${size2}, Valid Pixels: ${count2}`);
  console.log(`Mean NDVI (Sep 2021): ${meanNDVI1.toFixed(3)}`);
  console.log(`Mean NDVI (Sep 2022): ${meanNDVI2.toFixed(3)}`);

  // Did the NDVI decrease between Sep 2021 and Sep 2022?
  if (meanNDVI2 < meanNDVI1) {
    console.log('A'); // Yes, it decreased
  } else {
    console.log('B'); // No, it did not decrease (stayed same or increased)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
